namespace App\Http\Controllers\Dispatch;

use App\Http\Controllers\Controller;
use App\Models\RouteManifest;
use Illuminate\Http\Request;
use Illuminate\Http\JsonResponse;

class RouteDispatchController extends Controller
{
    public function reassign(Request $request, int $id): JsonResponse
    {
        if (!$request->user()->tokenCan('routes:update')) {
            return response()->json(['message' => 'Forbidden token capability'], 403);
        }

        $manifest = $request->user()->fleetCompany
            ->routeManifests()
            ->findOrFail($id);

        $manifest->update(['driver_id' => $request->input('driver_id')]);

        return response()->json(['message' => 'Driver reassigned', 'manifest' => $manifest]);
    }
}
